<script setup>
import {ref,computed,onMounted} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {House,Collection,Flag,Document,Setting,Upload,Download,Plus} from '@element-plus/icons-vue';
import {api} from './api';
import {columns,toRows,fromCSV,encodeCSV,download} from './utils/csv';
const menus=[['home','首页',House],['themes','主题管理',Collection],['levels','关卡管理',Flag],['questions','题库管理',Document],['rules','游戏规则',Setting]];
const page=ref('home'),data=ref({themes:[],levels:[],questions:[],rules:{}}),search=ref(''),themeFilter=ref(''),levelFilter=ref(''),statusFilter=ref(''),dialog=ref(false),editing=ref(false),form=ref({}),busy=ref(false),fileInput=ref(),pageNumber=ref(1),ruleDraft=ref({});
const title=computed(()=>menus.find(m=>m[0]===page.value)?.[1]);
const themeName=id=>data.value.themes.find(t=>t.id===id)?.name||id;
const levelName=id=>data.value.levels.find(l=>l.id===id)?.name||id;
const availableLevels=computed(()=>data.value.levels.filter(l=>l.themeId===form.value.themeId));
const filtered=computed(()=>{let rows=data.value[page.value]||[];return rows.filter(q=>(!themeFilter.value||q.themeId===themeFilter.value)&&(!levelFilter.value||q.levelId===levelFilter.value)&&(!statusFilter.value||q.reviewStatus===statusFilter.value)&&(!search.value||JSON.stringify(q).toLowerCase().includes(search.value.toLowerCase()))).sort((a,b)=>page.value==='levels'?a.themeId.localeCompare(b.themeId)||a.sort-b.sort:0)});
const visible=computed(()=>filtered.value.slice((pageNumber.value-1)*10,pageNumber.value*10));
async function run(fn){busy.value=true;try{data.value=await fn();ruleDraft.value={...data.value.rules};return true}catch(e){ElMessage.error(e.message||'操作失败，请重试');return false}finally{busy.value=false}}
onMounted(()=>run(()=>api.load()));
function navigate(id){page.value=id;search.value='';themeFilter.value='';levelFilter.value='';statusFilter.value='';pageNumber.value=1;ruleDraft.value={...data.value.rules}}
function open(row){editing.value=!!row;form.value=row?JSON.parse(JSON.stringify(row)):page.value==='themes'?{id:'',name:'',description:'',color:'#398f7d',enabled:true}:page.value==='levels'?{id:'',themeId:data.value.themes[0]?.id,name:'',sort:1,questionCount:10,timeLimit:300,points:10}:{id:'',themeId:data.value.themes[0]?.id,levelId:data.value.levels[0]?.id,title:'',options:['','','',''],answer:0,explanation:'',imageUrl:'',videoUrl:'',reviewStatus:'待审核'};dialog.value=true}
async function save(){if(!editing.value&&data.value[page.value].some(q=>q.id===form.value.id)){ElMessage.error('编号已存在，请换一个编号');return}if(page.value==='levels'&&editing.value){const old=data.value.levels.find(l=>l.id===form.value.id);if(old.themeId!==form.value.themeId&&data.value.questions.some(q=>q.levelId===old.id)){ElMessage.error('有题目的关卡不能更换主题');return}}if(await run(()=>api.save(page.value,form.value))){dialog.value=false;ElMessage.success('保存成功')}}
async function remove(row){try{await ElMessageBox.confirm(`确定删除“${row.name||row.title}”？`,'删除确认',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});if(await run(()=>api.remove(page.value,row.id)))ElMessage.success('已删除')}catch{}}
function exportCSV(template=false){download(`${page.value==='questions'?'题库':'关卡配置'}${template?'模板':''}.csv`,encodeCSV(template?[columns[page.value]]:toRows(page.value,filtered.value)));ElMessage.success(template?'模板已下载':'已导出当前筛选结果')}
async function importCSV(event){const file=event.target.files[0];event.target.value='';if(!file)return;try{const items=fromCSV(page.value,await file.text());if(!items.length)throw Error('文件中没有数据');await ElMessageBox.confirm(`导入${items.length}条数据；相同编号将更新，其余新增。整批校验通过后保存。`,'确认导入',{confirmButtonText:'导入',cancelButtonText:'取消'});if(await run(()=>api.import(page.value,items)))ElMessage.success(`已导入${items.length}条数据`)}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
const poolCount=id=>data.value.questions.filter(q=>q.levelId===id).length;
</script>
<template>
<div class="shell"><aside><div class="brand"><span class="brand-mark">趣</span><div>趣味闯关<small>小游戏管理工作台</small></div></div><div class="menu-label">内容与配置</div><el-menu :default-active="page" @select="navigate" background-color="transparent" text-color="#aebcd0" active-text-color="#fff"><el-menu-item v-for="m in menus" :key="m[0]" :index="m[0]"><el-icon><component :is="m[2]"/></el-icon><span>{{m[1]}}</span></el-menu-item></el-menu></aside>
<div class="workspace"><header><el-breadcrumb separator="/"><el-breadcrumb-item>管理工作台</el-breadcrumb-item><el-breadcrumb-item>{{title}}</el-breadcrumb-item></el-breadcrumb><div><span class="avatar">管</span></div></header><main v-loading="busy"><div class="page-heading"><div><div class="eyebrow">趣味闯关 / 内容运营</div><h1>{{title}}</h1><p>{{page==='home'?'从主题、关卡到题目，掌握游戏内容的准备进度。':page==='rules'?'统一配置闯关奖励与每日答题规则。':'维护游戏内容，修改后保存即可生效。'}}</p></div><el-button v-if="['themes','levels','questions'].includes(page)" type="primary" :icon="Plus" @click="open()">新增{{page==='themes'?'主题':page==='levels'?'关卡':'题目'}}</el-button></div>
<template v-if="page==='home'"><div class="stats"><article v-for="s in [['游戏主题',data.themes.length,'themes'],['关卡配置',data.levels.length,'levels'],['题库总量',data.questions.length,'questions'],['待审核题目',data.questions.filter(q=>q.reviewStatus==='待审核').length,'questions']]" @click="navigate(s[2])" tabindex="0" @keydown.enter="navigate(s[2])"><span>{{s[0]}}</span><strong>{{s[1]}}<small>项</small></strong><div>查看管理 →</div></article></div><section class="panel"><div class="panel-title"><h2>主题内容概览</h2><span>四个方向，一起探索湖南</span></div><div class="theme-grid"><article v-for="t in data.themes" :key="t.id" :style="{'--theme-color':t.color}"><div class="theme-line"/><h3>{{t.name}}</h3><p>{{t.description}}</p><div class="theme-numbers"><span>{{data.levels.filter(l=>l.themeId===t.id).length}} 个关卡</span><span>{{data.questions.filter(q=>q.themeId===t.id).length}} 道题目</span></div><el-button text type="primary" @click="navigate('questions');themeFilter=t.id">管理题目 →</el-button></article></div></section></template>
<section v-else-if="page==='rules'" class="panel rules"><h2>答题与积分</h2><el-form label-position="top"><el-form-item label="每关复活次数"><el-input-number v-model="ruleDraft.reviveCount" :min="0" :max="100"/></el-form-item><el-form-item label="每日积分上限"><el-input-number v-model="ruleDraft.dailyPointLimit" :min="0" :max="100000"/><p class="muted">0表示当日不获得积分。</p></el-form-item><el-form-item label="失败后的当日锁定"><el-switch v-model="ruleDraft.lockAfterFailure" active-text="启用"/></el-form-item><el-divider/><h3>各关通关积分</h3><p class="muted">积分为通关奖励，不是每题得分。在关卡管理中逐关调整。</p><el-table :data="data.levels"><el-table-column label="主题"><template #default="s">{{themeName(s.row.themeId)}}</template></el-table-column><el-table-column prop="name" label="关卡"/><el-table-column prop="points" label="通关积分"/></el-table><el-button class="save-rules" type="primary" @click="async()=>{if(await run(()=>api.save('rules',ruleDraft)))ElMessage.success('规则已保存')}">保存游戏规则</el-button></el-form></section>
<section v-else class="panel"><div class="toolbar"><el-input v-model="search" placeholder="搜索名称、编号或内容" clearable @input="pageNumber=1"/><el-select v-if="page!=='themes'" v-model="themeFilter" placeholder="全部主题" clearable @change="pageNumber=1;levelFilter='' "><el-option v-for="t in data.themes" :label="t.name" :value="t.id"/></el-select><el-select v-if="page==='questions'" v-model="levelFilter" placeholder="全部关卡" clearable @change="pageNumber=1"><el-option v-for="l in data.levels.filter(l=>!themeFilter||l.themeId===themeFilter)" :label="themeName(l.themeId)+' / '+l.name" :value="l.id"/></el-select><el-select v-if="page==='questions'" v-model="statusFilter" placeholder="审核状态" clearable @change="pageNumber=1"><el-option v-for="s in ['待审核','已通过','已退回']" :label="s" :value="s"/></el-select></div><div v-if="page!=='themes'" class="csv-tools"><el-button :icon="Upload" @click="fileInput.click()">CSV导入</el-button><el-button :icon="Download" @click="exportCSV()">CSV导出</el-button><el-button text @click="exportCSV(true)">下载模板</el-button><span>相同编号更新 · 新编号新增</span><input ref="fileInput" hidden type="file" accept=".csv,text/csv" @change="importCSV"/></div>
<el-table :data="visible" stripe empty-text="暂无数据，请新增或导入内容" row-key="id"><el-table-column prop="id" label="编号" width="155"/><el-table-column v-if="page!=='themes'" label="主题" width="110"><template #default="s">{{themeName(s.row.themeId)}}</template></el-table-column><el-table-column :prop="page==='questions'?'title':'name'" :label="page==='questions'?'题干':'名称'" min-width="220" show-overflow-tooltip/><template v-if="page==='themes'"><el-table-column prop="description" label="主题说明" min-width="150"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column></template><template v-if="page==='levels'"><el-table-column prop="sort" label="排序" width="75"/><el-table-column prop="questionCount" label="每轮题数" width="100"/><el-table-column prop="timeLimit" label="时间（秒）" width="110"/><el-table-column prop="points" label="通关积分" width="100"/><el-table-column label="题池容量" width="100"><template #default="s"><el-tag :type="poolCount(s.row.id)<s.row.questionCount?'warning':'success'">{{poolCount(s.row.id)}} 题</el-tag></template></el-table-column></template><template v-if="page==='questions'"><el-table-column label="关卡" min-width="160"><template #default="s">{{levelName(s.row.levelId)}}</template></el-table-column><el-table-column label="答案" width="70"><template #default="s">{{'ABCD'[s.row.answer]}}</template></el-table-column><el-table-column prop="reviewStatus" label="审核状态" width="100"/></template><el-table-column label="操作" width="140" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{filtered.length}} 条</span><el-pagination v-model:current-page="pageNumber" :total="filtered.length" :page-size="10" layout="prev, pager, next"/></div></section>
</main></div>
<el-dialog v-model="dialog" :title="(editing?'编辑':'新增')+title.replace('管理','')" width="min(640px, 94vw)" destroy-on-close><el-form label-position="top"><div class="form-grid"><el-form-item label="唯一编号"><el-input v-model="form.id" :disabled="editing" placeholder="例如 red-5 或 Q-001"/></el-form-item><el-form-item v-if="page!=='themes'" label="所属主题"><el-select v-model="form.themeId" @change="form.levelId='' "><el-option v-for="t in data.themes" :label="t.name" :value="t.id"/></el-select></el-form-item></div>
<template v-if="page==='themes'"><el-form-item label="主题名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="主题说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="主题颜色"><el-color-picker v-model="form.color"/></el-form-item><el-form-item label="启用主题"><el-switch v-model="form.enabled"/></el-form-item></template>
<template v-if="page==='levels'"><el-form-item label="关卡名称"><el-input v-model="form.name"/></el-form-item><div class="form-grid"><el-form-item v-for="f in [['sort','排序（同主题内）'],['questionCount','每轮题目数量'],['timeLimit','答题时间（秒）'],['points','通关积分']]" :label="f[1]"><el-input-number v-model="form[f[0]]" :min="f[0]==='points'?0:1" :max="100000"/></el-form-item></div></template>
<template v-if="page==='questions'"><el-form-item label="所属关卡"><el-select v-model="form.levelId"><el-option v-for="l in availableLevels" :label="l.name" :value="l.id"/></el-select></el-form-item><el-form-item label="题干（单选题）"><el-input v-model="form.title" type="textarea" :rows="2"/></el-form-item><div class="form-grid"><el-form-item v-for="(v,i) in form.options" :label="'选项 '+'ABCD'[i]"><el-input v-model="form.options[i]"/></el-form-item></div><el-form-item label="正确答案"><el-radio-group v-model="form.answer"><el-radio-button v-for="(v,i) in form.options" :value="i">{{'ABCD'[i]}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="题目解析"><el-input v-model="form.explanation" type="textarea"/></el-form-item><el-form-item label="图片地址（可选）"><el-input v-model="form.imageUrl" placeholder="https://…"/></el-form-item><el-form-item label="视频地址（可选）"><el-input v-model="form.videoUrl" placeholder="https://…"/></el-form-item><el-form-item label="审核状态"><el-select v-model="form.reviewStatus"><el-option v-for="s in ['待审核','已通过','已退回']" :label="s" :value="s"/></el-select></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog>
</div>
</template>
